import os,re
root='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'
def path(mod):
    return os.path.join(root, mod.replace('.','/')+'.lean')
seen=set()
def walk(mod):
    if mod in seen: return
    seen.add(mod)
    p=path(mod)
    if not os.path.exists(p): return
    for line in open(p):
        m=re.match(r'import (AlgebraicJacobian[\w.]*)',line)
        if m: walk(m.group(1))
for m in ['AlgebraicJacobian.Picard.DivisorFamilyAffMap','AlgebraicJacobian.Picard.DivisorFamilyAffFunctorCompare','AlgebraicJacobian.Picard.DivRepGlobalAffLift']:
    walk(m)
print('closure size (AJ modules):',len(seen))
print('P1Aut in closure:', any('P1Aut' in m for m in seen))
EOF
